import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.C8nVztS1.js";const h=JSON.parse('{"title":"Vitest Browser Mode","description":"Why recipe e2e stays on Node + Playwright — Browser Mode is a separate optional track.","frontmatter":{"title":"Vitest Browser Mode","description":"Why recipe e2e stays on Node + Playwright — Browser Mode is a separate optional track.","outline":"deep"},"headers":[],"relativePath":"guide/browser-mode.md","filePath":"guide/browser-mode.md","lastUpdated":1790411047000}'),s={name:"guide/browser-mode.md"};function i(d,e,n,l,p,c){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="vitest-browser-mode" tabindex="-1">Vitest Browser Mode <a class="header-anchor" href="#vitest-browser-mode" aria-label="Permalink to &quot;Vitest Browser Mode&quot;">​</a></h1><p><strong>Not part of recipe e2e.</strong> Vitest <a href="https://vitest.dev/guide/browser/" target="_blank" rel="noreferrer">Browser Mode</a> runs component tests inside a real browser via Vite. That is a different product surface from untestutils recipes (<code>prepare</code> → <code>start</code> → live URL).</p><table tabindex="0"><thead><tr><th>Track</th><th>Runner</th><th>Target</th></tr></thead><tbody><tr><td>Recipe e2e (primary)</td><td>Vitest Node + Playwright / Playwright Test</td><td>Live URL from <code>leaseTarget</code> / harness</td></tr><tr><td>Nuxt unit</td><td><code>environment: &#39;untestutils&#39;</code></td><td>In-process Vue/Nuxt</td></tr><tr><td>Browser Mode (optional, later)</td><td>Vitest browser provider</td><td>In-Vite UI components</td></tr></tbody></table><h2 id="nuxt-unit-in-browser-mode" tabindex="-1">Nuxt unit in Browser Mode <a class="header-anchor" href="#nuxt-unit-in-browser-mode" aria-label="Permalink to &quot;Nuxt unit in Browser Mode&quot;">​</a></h2><p>When <code>test.browser.enabled</code> is on and <code>environment: &#39;untestutils&#39;</code>, setup uses <code>runtime/browser-entry</code> (not the Node DOM <code>entry</code>):</p><ol><li>Sets <code>__NUXT_VITEST_ENVIRONMENT_BROWSER_ENTRY__</code> so the Node entry skips</li><li>Calls <code>setupWindow</code> only if the env is not already prepared</li><li>Registers the same worker-aware boot path as Node (<code>registerNuxtSetupEntry</code> / <code>appIsolation</code>)</li></ol><p>This matches the <a href="https://github.com/nuxt/test-utils/pull/1821" target="_blank" rel="noreferrer">nuxt/test-utils#1821</a> browser-entry shape, with untestutils’ opt-in <code>appIsolation: &#39;worker&#39;</code> (see <a href="/untestutils/guide/vitest#appisolation-worker-opt-in">Vitest — appIsolation</a>) instead of always-memoize.</p><p>Default CI does <strong>not</strong> run a real <code>@vitest/browser</code> job — Browser Mode stays <strong>Experimental</strong> in the <a href="/untestutils/guide/support-matrix">Support matrix</a> until that job exists. Enable Browser Mode in a dedicated project when you need real Chromium; Nuxt helpers remain mock-friendly without it.</p><h2 id="_1-0-stance" tabindex="-1">1.0 stance <a class="header-anchor" href="#_1-0-stance" aria-label="Permalink to &quot;1.0 stance&quot;">​</a></h2><ul><li>Classic <strong>Node + Playwright</strong> against a leased URL remains the primary e2e path.</li><li>A dedicated Browser Mode package/helpers may appear <strong>after</strong> 1.0 if dogfood appears — it will not replace recipes.</li><li>Do not mix Browser Mode config with the e2e <code>untestutils()</code> plugin in one project.</li></ul><p>See <a href="/untestutils/guide/support-matrix">Support matrix</a> · <a href="/untestutils/roadmap">Roadmap</a>.</p>',11)])])}const m=t(s,[["render",i]]);export{h as __pageData,m as default};
